import{_ as a,c as n,o as t,ag as r}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"Frontend learning path","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/index.md","filePath":"frontend/index.md"}'),i={name:"frontend/index.md"};function o(s,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="frontend-learning-path" tabindex="-1">Frontend learning path <a class="header-anchor" href="#frontend-learning-path" aria-label="Permalink to “Frontend learning path”">​</a></h1><p>Build a usable document before adding a type system, component runtime or full-stack framework. The shared domain is a small public course catalogue; P-328 grows it into an authenticated management screen. <strong>All learner practice remains outstanding.</strong></p><h2 id="frontend-foundations" tabindex="-1"><span class="hub-section-number">1 </span>Frontend foundations <a class="header-anchor" href="#frontend-foundations" aria-label="Permalink to “1 Frontend foundations”">​</a></h2><ul><li><a href="./html-browser.html">HTML, browser behavior and accessibility</a>, then the ordered <a href="./../senior_growth/A11y/">accessibility lessons</a>.</li><li><a href="./../senior_growth/CSS/">CSS layout and cascade</a>, including intrinsic sizing and visible interaction states.</li><li><a href="./javascript.html">JavaScript ownership and asynchronous execution</a>, then <a href="./typescript.html">TypeScript contracts</a>.</li></ul><h2 id="components-and-application-architecture" tabindex="-1"><span class="hub-section-number">2 </span>Components and application architecture <a class="header-anchor" href="#components-and-application-architecture" aria-label="Permalink to “2 Components and application architecture”">​</a></h2><ul><li><a href="./react.html">React rendering and synchronization</a>, followed by forms, routing and component contracts.</li><li><a href="./next.html">Next.js and UI architecture</a>: use React and HTTP prerequisites before server/client caching or mutations.</li></ul><h2 id="performance-and-senior-investigation" tabindex="-1"><span class="hub-section-number">3 </span>Performance and senior investigation <a class="header-anchor" href="#performance-and-senior-investigation" aria-label="Permalink to “3 Performance and senior investigation”">​</a></h2><p>Follow the required <a href="./performance/">frontend performance path</a> after browser/JavaScript foundations, then apply the React/Next sections after those prerequisites. It merges the EPAM performance modules with existing references: measurement, loading and bundles, images, CSS/fonts, responsiveness and caching. Complete the <a href="./../practice/frontend/performance/">three performance hometasks</a> on the same application; optional specialist extensions follow observed needs.</p><h2 id="examples-practice-and-verification" tabindex="-1"><span class="hub-section-number">4 </span>Examples, practice and verification <a class="header-anchor" href="#examples-practice-and-verification" aria-label="Permalink to “4 Examples, practice and verification”">​</a></h2><p><a href="./coverage-map.html">Coverage and ownership map</a> identifies canonical explanations and overlap decisions. <a href="./../workbench/frontend/">Workbench</a> contains reference implementations; <a href="./../practice/frontend/">practice sequence</a> defines learner deliverables separately. <a href="./verification.html">Verification and limits</a> records the evidence behind the references.</p><h2 id="boundaries" tabindex="-1"><span class="hub-section-number">5 </span>Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to “5 Boundaries”">​</a></h2><p>Browser DOM, input, focus, layout and navigation belong here. <a href="./../node-js/">Node.js</a> owns server runtime mechanics, streams and backend/database/deployment implementation. <a href="./../cs-foundations/">CS foundations</a> owns algorithm correctness and complexity. <a href="./../applied-ai/">Applied AI</a> owns retrieval and agent systems; its existing React streaming port is an optional consumer of these UI foundations.</p><p>Redux, advanced conditional types, custom composite widgets, virtualization, microfrontends and framework migrations are optional after the essential path. Choose a tool to meet an observed requirement rather than implement every comparison in the reference catalogue.</p>',13)])])}const f=a(i,[["render",o]]);export{m as __pageData,f as default};
